package br.com.multisaude.agenda;

import java.sql.*; import java.time.*; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository;
import static br.com.multisaude.agenda.AgendaModels.*;

@Repository public class AgendaRepository {
 private static final String COLS="id,unidade_id,profissional_id,paciente_id,procedimento_id,lower(periodo) inicio,upper(periodo) fim,status,observacao,versao,canal,remarcado_de";
 private final JdbcTemplate jdbc; public AgendaRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public List<ProcedureView> procedures(){return jdbc.query("SELECT id,nome,codigo_tuss,tipo,duracao_min,valor_centavos,ativo FROM clinica.procedimentos WHERE ativo ORDER BY nome",(r,n)->new ProcedureView(r.getObject("id",UUID.class),r.getString("nome"),r.getString("codigo_tuss"),r.getString("tipo"),r.getObject("duracao_min",Integer.class),(Long)r.getObject("valor_centavos"),r.getBoolean("ativo")));}
 public ProcedureView createProcedure(CreateProcedureRequest x,UUID tenant){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO clinica.procedimentos(id,tenant_id,nome,codigo_tuss,tipo,duracao_min,valor_centavos) VALUES(?,?,?,?,?,?,?)",id,tenant,x.nome().trim(),blank(x.codigoTuss()),x.tipo().trim(),x.duracaoMin()==null||x.duracaoMin()==0?null:x.duracaoMin(),x.valorCentavos());return jdbc.queryForObject("SELECT id,nome,codigo_tuss,tipo,duracao_min,valor_centavos,ativo FROM clinica.procedimentos WHERE id=?",(r,n)->new ProcedureView(r.getObject("id",UUID.class),r.getString("nome"),r.getString("codigo_tuss"),r.getString("tipo"),r.getObject("duracao_min",Integer.class),(Long)r.getObject("valor_centavos"),r.getBoolean("ativo")),id);}
 public List<AppointmentView> appointments(UUID unit,UUID professional,OffsetDateTime from,OffsetDateTime to){return jdbc.query("SELECT "+COLS+" FROM clinica.agendamentos WHERE unidade_id=? AND profissional_id=? AND periodo && tstzrange(?,?,'[)') ORDER BY periodo",(r,n)->view(r),unit,professional,Timestamp.from(from.toInstant()),Timestamp.from(to.toInstant()));}
 /** Referências precisam existir no tenant (RLS filtra os demais), estar ativas e o profissional deve atender na unidade. */
 public boolean referencesAreValid(UUID unit,UUID professional,UUID patient,UUID procedure){
  return Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM clinica.pacientes WHERE id=? AND ativo) AND EXISTS(SELECT 1 FROM clinica.procedimentos WHERE id=? AND ativo) AND EXISTS(SELECT 1 FROM clinica.profissionais p JOIN clinica.profissional_unidades u ON u.tenant_id=p.tenant_id AND u.profissional_id=p.id WHERE p.id=? AND p.ativo AND u.unidade_id=?)",Boolean.class,patient,procedure,professional,unit));
 }
 /** Mesma regra da constraint agendamento_profissional_sem_conflito, para responder 409 sem abortar a transação. */
 /** excludeId ignora um agendamento (o que está sendo remarcado) na checagem; null não exclui nenhum. */
 public boolean hasConflict(UUID professional,OffsetDateTime from,OffsetDateTime to,UUID excludeId){
  return Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM clinica.agendamentos WHERE profissional_id=? AND periodo && tstzrange(?,?,'[)') AND status NOT IN ('cancelado','nao_compareceu','remarcado') AND id IS DISTINCT FROM ?)",Boolean.class,professional,Timestamp.from(from.toInstant()),Timestamp.from(to.toInstant()),excludeId));
 }
 public AppointmentView createAppointment(CreateAppointmentRequest x,UUID tenant,UUID creator,UUID rescheduledFrom){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO clinica.agendamentos(id,tenant_id,unidade_id,profissional_id,paciente_id,procedimento_id,periodo,observacao,criado_por,canal,remarcado_de) VALUES(?,?,?,?,?,?,tstzrange(?,?,'[)'),?,?,?,?)",id,tenant,x.unidadeId(),x.profissionalId(),x.pacienteId(),x.procedimentoId(),Timestamp.from(x.inicio().toInstant()),Timestamp.from(x.fim().toInstant()),blank(x.observacao()),creator,x.canal()==null?"clinica":x.canal(),rescheduledFrom);return jdbc.queryForObject("SELECT "+COLS+" FROM clinica.agendamentos WHERE id=?",(r,n)->view(r),id);}
 /** Bloqueia a linha até o fim da transação para que duas ações simultâneas não decidam sobre o mesmo estado. */
 public Optional<AppointmentView> lockAppointment(UUID id){return jdbc.query("SELECT "+COLS+" FROM clinica.agendamentos WHERE id=? FOR UPDATE",(r,n)->view(r),id).stream().findFirst();}
 public Optional<AppointmentOwner> appointmentOwner(UUID id){return jdbc.query("SELECT profissional_id,unidade_id FROM clinica.agendamentos WHERE id=?",(r,n)->new AppointmentOwner(r.getObject(1,UUID.class),r.getObject(2,UUID.class)),id).stream().findFirst();}
 public boolean motiveExists(int id){return Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM clinica.agendamento_motivos WHERE id=?)",Boolean.class,id));}
 public List<MotiveView> motives(){return jdbc.query("SELECT id,nome,origem FROM clinica.agendamento_motivos ORDER BY id",(r,n)->new MotiveView(r.getInt("id"),r.getString("nome"),r.getString("origem")));}
 /** Falso quando a versão mudou desde a leitura. */
 public boolean changeStatus(UUID id,int version,String to){return jdbc.update("UPDATE clinica.agendamentos SET status=?,versao=versao+1,atualizado_em=now() WHERE id=? AND versao=?",to,id,version)==1;}
 public void addHistory(UUID tenant,UUID appointment,String from,String to,Integer motive,String note,UUID user){jdbc.update("INSERT INTO clinica.agendamento_historico(tenant_id,agendamento_id,de,para,motivo_id,observacao,usuario_id) VALUES(?,?,?,?,?,?,?)",tenant,appointment,from,to,motive,blank(note),user);}
 public List<HistoryView> history(UUID appointment){return jdbc.query("SELECT agendamento_id,de,para,motivo_id,observacao,usuario_id,em FROM clinica.agendamento_historico WHERE agendamento_id=? ORDER BY id",(r,n)->new HistoryView(r.getObject("agendamento_id",UUID.class),r.getString("de"),r.getString("para"),(Integer)r.getObject("motivo_id"),r.getString("observacao"),r.getObject("usuario_id",UUID.class),r.getObject("em",OffsetDateTime.class)),appointment);}
 private AppointmentView view(ResultSet r)throws SQLException{return new AppointmentView(r.getObject("id",UUID.class),r.getObject("unidade_id",UUID.class),r.getObject("profissional_id",UUID.class),r.getObject("paciente_id",UUID.class),r.getObject("procedimento_id",UUID.class),r.getObject("inicio",OffsetDateTime.class),r.getObject("fim",OffsetDateTime.class),r.getString("status"),r.getString("observacao"),r.getInt("versao"),r.getString("canal"),r.getObject("remarcado_de",UUID.class));}
 private static String blank(String x){return x==null||x.isBlank()?null:x.trim();}
}
